sp_widget.css:
.tm-detail-card {
    background: #ffffff;
    border-radius: 20px;
    padding: 28px;
    box-shadow: 0 10px 30px rgba(0, 0, 0, 0.08);
    height: 100%;
    display: flex;
    flex-direction: column;
}

.detail-header h3 {
    margin: 0 0 20px 0;
    font-size: 19px;
    font-weight: 700;
    color: #0f172a;
}

/* Priority Badge */
.priority-badge {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    padding: 8px 16px;
    border-radius: 30px;
    font-weight: 600;
    font-size: 13.5px;
    margin-bottom: 18px;
}

.high-priority {
    background: #fee2e2;
    color: #dc2626;
}

/* Main Alert Info */
.alert-main-info h4 {
    margin: 0 0 6px 0;
    font-size: 17px;
    font-weight: 600;
    color: #0f172a;
}

.missed-time {
    color: #ef4444;
    font-size: 14px;
    margin: 0;
    font-weight: 500;
}

.detail-divider {
    border: none;
    border-top: 1px solid #e2e8f0;
    margin: 22px 0;
}

/* Form Styling */
.form-group {
    margin-bottom: 20px;
}

.form-group label {
    display: block;
    font-size: 13px;
    font-weight: 600;
    color: #475569;
    margin-bottom: 8px;
}

.form-control {
    width: 100%;
    padding: 12px 14px;
    border: 1px solid #e2e8f0;
    border-radius: 10px;
    font-size: 14px;
    color: #1e2937;
    transition: all 0.3s ease;
}

.form-control:focus {
    border-color: #14b8a6;
    box-shadow: 0 0 0 3px rgba(20, 184, 166, 0.15);
    outline: none;
}

textarea.form-control {
    resize: vertical;
}

/* Footer Button */
.detail-footer {
    margin-top: auto;
    padding-top: 12px;
    text-align: right;
}

.btn-resolve {
    background: #10b981;
    color: white;
    border: none;
    padding: 12px 24px;
    border-radius: 12px;
    font-weight: 600;
    font-size: 14px;
    display: inline-flex;
    align-items: center;
    gap: 8px;
    transition: all 0.3s ease;
}

.btn-resolve:hover {
    background: #059669;
    transform: translateY(-2px);
    box-shadow: 0 8px 20px rgba(16, 185, 129, 0.3);
}
